            {
                AmmunitionBinaryWriteTranslation.WriteBinaryExtraData(
                    writer: writer,
                    item: item);
            }
            StringBinaryTranslation.Instance.WriteNullable(
                writer: writer,
                item: item.ShortName,
                header: translationParams.ConvertToCustom(RecordTypes.ONAM),
